          'Quality_mc',
          'Music_mc',
          'Sounds_mc',
          'ScreenShake_mc',
          'EfficientMode_mc',
          'btnHotkeys_mc',
          'btnBack_mc',
        ],
        200,
      );
    else retract(this.settings, true);
    if (active && hotkeys) {
      enter(
        this.hotkeys,
        SETTINGS_SCREEN.pause.hotkeys.pieces,
        ['Title_mc', 'Up_mc', 'Down_mc', 'Left_mc', 'Right_mc', 'Paused_mc'],
